export function heritageCatalogItem(dayNumber) {
  const day = Number(dayNumber);
  if (!Number.isInteger(day) || day < 1 || day > HERITAGE_CATALOG.length) return null;
  return HERITAGE_CATALOG[day - 1] || null;
}
export function heritageCatalogStats() {
  const ids = new Set(HERITAGE_CATALOG.map((x) => String(x.unescoId)));
  const countries = new Set(HERITAGE_CATALOG.map((x) => x.countryEn));
  const categories = HERITAGE_CATALOG.reduce((acc,x)=>(acc[x.category]=(acc[x.category]||0)+1,acc),{});
  return { count: HERITAGE_CATALOG.length, uniqueIds: ids.size, countries: countries.size, categories };
}
